import asyncio

erp = {"in_flight": 0, "peak": 0}


async def fake_erp(po: str) -> dict:
    """A fake ERP API: answers in 0.01 s; "boom" fails with ConnectionError and "hang" takes 5 s.
    erp["peak"] records the most calls ever in flight at once."""
    erp["in_flight"] += 1
    erp["peak"] = max(erp["peak"], erp["in_flight"])
    try:
        if po == "hang":
            await asyncio.sleep(5)
        await asyncio.sleep(0.01)
        if po == "boom":
            raise ConnectionError("ERP unavailable")
        return {"po": po, "status": "open"}
    finally:
        erp["in_flight"] -= 1

p-request-id-middleware-with-contextvars.solution:
import contextvars
import uuid

request_id: contextvars.ContextVar[str | None] = contextvars.ContextVar("request_id", default=None)

def log(message: str) -> None:
    lines.append({"message": message, "request_id": request_id.get()})

class RequestIdMiddleware:
    def __init__(self, app) -> None:
        self.app = app

    async def __call__(self, scope, receive, send) -> None:
        if scope["type"] != "http":
            return await self.app(scope, receive, send)
        headers = dict(scope["headers"])
        rid = headers.get(b"x-request-id", b"").decode() or uuid.uuid4().hex
        token = request_id.set(rid)

        async def send_with_id(message) -> None:
            if message["type"] == "http.response.start":
                message["headers"] = [*message.get("headers", []), (b"x-request-id", rid.encode())]
            await send(message)

        try:
            await self.app(scope, receive, send_with_id)
        finally:
            request_id.reset(token)
